  addWave(acc, p, t, damp, vec2(0.860, 0.510), 47.0, 0.440);
  addWave(acc, p, t, damp, vec2(0.552, -0.834), 28.5, 0.235);
  addWave(acc, p, t, damp, vec2(-0.921, 0.390), 15.0, 0.112);
